-- The morning briefing (22 Oct): a fictional Travel list (two rows new today) and a pushed briefing.
UPDATE leads SET imported_at = datetime('now') WHERE uid = 'web-redesign-demo/atelier-meridian';
-- Fictional issuer and accounts: nothing real prints on a demo invoice.
-- The issuer switch (0034): two fictional profiles, so a demo invoice can pick one.
-- My info (F19): a fictional person and brands, so the screen never falls back to the real defaults.

-- Quick personalization (culling mode): stable codes in payload.extra.code, as LEADS writes them.
-- Fictional Suisse romande leads (S…), and codes on three existing demo leads (B…, F…).
UPDATE leads SET payload = json_set(payload, '$.extra.code', 'B1') WHERE uid = 'web-redesign-demo/atelier-meridian';
UPDATE leads SET payload = json_set(payload, '$.extra.code', 'B2') WHERE uid = 'web-redesign-demo/studio-berg';
-- F is France: the demo lead coded F1 sits in a French town.
UPDATE leads SET payload = json_set(payload, '$.extra.code', 'F1'), city = 'Lille', area = 'Nord', region = 'Hauts-de-France', country = 'France' WHERE uid = 'web-redesign-demo/cabinet-rousseau';
-- Two more coded rows, so Quick personalization's field filter has more than one field.
UPDATE leads SET category = 'Aesthetic clinic', payload = json_set(payload, '$.extra.code', 'B3') WHERE uid = 'web-redesign-demo/clinique-aurore';
UPDATE leads SET payload = json_set(payload, '$.extra.code', 'B4') WHERE uid = 'web-redesign-demo/maison-verhoeven';

-- Travel stays (P…): Andy's personal list in the culling screen. Fictional places; codes, what each
-- offers (research) and how to apply, so the demo shows an email row and a portal row.
UPDATE leads SET payload = json_set(payload, '$.extra.code', 'P1', '$.research', 'Offers: private room with bathroom, two meals a day, wifi · wants a yoga teacher three mornings a week', '$.evidence', 'Minimum stay four weeks; a short video introduction with the application; Spanish basics help.'), contact = 'https://www.workaway.info/en/host/demo-casa-alba', contact_type = 'portal' WHERE uid = 'travel-volunteer-stays/casa-alba';
UPDATE leads SET payload = json_set(payload, '$.extra.code', 'P2', '$.research', 'Offers: dorm bed and breakfast, lake kayak · looking for a booking page'), email = 'hola@lago-azul.example', contact = 'hola@lago-azul.example', contact_type = 'email' WHERE uid = 'travel-volunteer-stays/lago-azul';
UPDATE leads SET payload = json_set(payload, '$.extra.code', 'P3', '$.research', 'Offers: shared room, all meals from the farm · help with the cacao harvest and a weekly yoga class'), contact = 'https://www.worldpackers.com/positions/demo-finca-sol', contact_type = 'portal' WHERE uid = 'travel-volunteer-stays/finca-sol';
UPDATE leads SET payload = json_set(payload, '$.extra.code', 'P4', '$.research', 'Offers: private cabin by the beach, surf lessons · wants a new website'), contact = 'https://example.com/costa-verde/contact', contact_type = 'form' WHERE uid = 'travel-volunteer-stays/costa-verde';

